    36→            GameProfileManager profileManager = Sponge.getServer().getGameProfileManager();
    37→            ProfileProperty profileProperty = profileManager.createProfileProperty(SkinProperty.SKIN_KEY
    38→                    , targetSkin.getEncodedValue(), targetSkin.getSignature());
    39→            profile.getPropertyMap().put(SkinProperty.SKIN_KEY, profileProperty);
    40→        }
